import{_ as n,C as i,o as d,c as l,a2 as o,E as s,j as e,a}from"./chunks/framework.CGSzHL4z.js";const f=JSON.parse('{"title":"The Library","description":"","frontmatter":{},"headers":[],"relativePath":"features/library.md","filePath":"features/library.md","lastUpdated":1792713747000}'),h={name:"features/library.md"};function p(c,t,g,b,u,m){const r=i("Screenshot");return d(),l("div",null,[t[0]||(t[0]=o('<h1 id="the-library" tabindex="-1">The Library <a class="header-anchor" href="#the-library" aria-label="Permalink to &quot;The Library&quot;">​</a></h1><p>The Library holds ready-made settings you can drop into a scene: eases, generators, constraints, drivers, Motion Warps and poses. Each tab has built-in presets plus the ones you save yourself, so a camera shake or a look-at-player aim you tuned once is a double click away in every scene.</p><h2 id="opening-it" tabindex="-1">Opening it <a class="header-anchor" href="#opening-it" aria-label="Permalink to &quot;Opening it&quot;">​</a></h2><p>The Library is a tab in the Hub, next to the Inspector. Like any Hub tab it can pop out into its own window (right click the tab &gt; <strong>Pop out</strong>). Inside it, the tabs are <strong>Easing</strong>, <strong>Generators</strong>, <strong>Constraints</strong>, <strong>Drivers</strong>, <strong>Warps</strong> and <strong>Poses</strong>, with a <strong>Search</strong> box that filters the open tab. When the tabs don&#39;t all fit, the strip scrolls sideways with the mouse wheel.</p><h2 id="adding-a-preset" tabindex="-1">Adding a preset <a class="header-anchor" href="#adding-a-preset" aria-label="Permalink to &quot;Adding a preset&quot;">​</a></h2><p>Every tab except Easing and Poses adds blocks to Timeline rows, and they all work the same way:</p><table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Pick a preset</td><td>Click it</td></tr><tr><td>Add it to the selected Timeline rows at the playhead</td><td>Double click it, or press <strong>Add to selected rows</strong></td></tr><tr><td>Add it to one row at a frame</td><td>Drag it from the Library onto a row in the Timeline</td></tr><tr><td>Rename or delete one of your own</td><td>Right click it</td></tr></tbody></table><p>Adding keeps you on the Library tab so the next add is one click. The new blocks are selected, the Inspector tab gets its dot, and the status bar says &quot;Added 2 blocks. The Inspector tab shows them.&quot; Turn on <strong>Settings &gt; Timeline &gt; Show added blocks in the Inspector</strong> to jump to the Inspector instead.</p><p>Rows a preset can&#39;t drive are skipped, and an actor row takes the preset on its root. A preset that aims at or reads a player, the player&#39;s camera or a tagged object uses the scene&#39;s actor of that kind. When the scene has none, a card offers to add one first.</p><h2 id="easing" tabindex="-1">Easing <a class="header-anchor" href="#easing" aria-label="Permalink to &quot;Easing&quot;">​</a></h2><p>The ease presets from the Ease view, under <strong>Built in</strong> and <strong>Saved</strong>. Double click a card or press <strong>Apply to selection</strong> to put it on the selected keys&#39; segments. See <a href="./easing">Easing and curves</a>.</p><h2 id="generators" tabindex="-1">Generators <a class="header-anchor" href="#generators" aria-label="Permalink to &quot;Generators&quot;">​</a></h2>',12)),s(r,{name:"lib-generators",caption:"The Generators tab: the Screen effects group, Shake with its Handheld, Explosion and Rumble presets, then Wiggle, Oscillate, Flicker / Strobe / Pulse, Spin, Recoil, Overshoot / Settle, Stepped and Hold / Fade."}),t[1]||(t[1]=e("p",null,[e("strong",null,"Built in"),a(" lists the "),e("strong",null,"Screen effects"),a(' group, then each generator with its description: Shake, Wiggle, Oscillate, Flicker / Strobe / Pulse, Spin, Recoil, Overshoot / Settle, Stepped, Hold / Fade, Cycle / Flipbook and Typewriter. Click one to open its presets, each with its settings in a line ("Amplitude 0.40, 6 Hz, no decay"). The '),e("strong",null,"Screen effects"),a(" group (Fade to black, Fade from black, Flash white, Letterbox, Vignette pulse) always goes on the scene's screen effects at the playhead, whatever is selected, and adds the screen effects first when the scene has none. See "),e("a",{href:"./generators"},"Generators"),a(".")],-1)),t[2]||(t[2]=e("h2",{id:"constraints",tabindex:"-1"},[a("Constraints "),e("a",{class:"header-anchor",href:"#constraints","aria-label":'Permalink to "Constraints"'},"​")],-1)),s(r,{name:"lib-constraints",caption:"The Constraints tab: Damped Track (Look at player), Locked Track (Turret), Horizon Lock, Face Motion, Delay (Echo), Floor (Feet on the floor), and My presets."}),t[3]||(t[3]=o('<p><strong>Built in</strong> lists Damped Track, Locked Track, Horizon Lock, Face Motion, Delay and Floor. The built-in presets include <strong>Look at player</strong> (aims at the local player&#39;s head, fading out between 5 and 15 studs), <strong>Turret</strong>, <strong>Level horizon</strong>, <strong>Bank into turns</strong>, <strong>Echo</strong> and <strong>Feet on the floor</strong> (Floor on the feet, resolved by bending the limbs). They go on the selected root and joint rows; property and channel rows are skipped. See <a href="./constraints-and-drivers">Constraints, drivers and Motion Warp</a>.</p><h2 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;Drivers&quot;">​</a></h2>',2)),s(r,{name:"lib-drivers",caption:"The Drivers tab: Distance (Dolly zoom, Proximity glow), Speed (Speed trail, Engine pitch) and Copy (Match colour)."}),t[4]||(t[4]=o('<table tabindex="0"><thead><tr><th>Preset</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Dolly zoom</strong></td><td>A camera&#39;s FieldOfView goes from 70 to 30 as a target moves 5 to 40 studs away</td></tr><tr><td><strong>Proximity glow</strong></td><td>Brightness goes from 3 to 0 as the nearest player comes within 20 studs</td></tr><tr><td><strong>Speed trail</strong></td><td>A Trail&#39;s width goes from 0 to 2 with speed</td></tr><tr><td><strong>Engine pitch</strong></td><td>A sound&#39;s PlaybackSpeed goes from 0.8 to 2 with speed, smoothed over 4 frames</td></tr><tr><td><strong>Match colour</strong></td><td>Copies Color from another Color</td></tr></tbody></table><p>Drivers added from the Library cover the whole scene.</p><h2 id="warps" tabindex="-1">Warps <a class="header-anchor" href="#warps" aria-label="Permalink to &quot;Warps&quot;">​</a></h2>',3)),s(r,{name:"lib-warps",caption:"The Warps tab: Projectiles (Fireball lob, Homing missile, Coin magnet) and Reaching (Crane claw, Dragon bite, Tentacle)."}),t[5]||(t[5]=o('<p><strong>Projectiles</strong> fly an actor to its target: <strong>Fireball lob</strong> (a Lob at 30 studs a second), <strong>Homing missile</strong> (follows the target) and <strong>Coin magnet</strong> (straight, at 40 studs a second). <strong>Reaching</strong> bends a joint chain toward it: <strong>Crane claw</strong>, <strong>Dragon bite</strong> and <strong>Tentacle</strong>. A warp preset goes on the first selected row and picks its target the way a new warp does. A reaching preset on an actor or root row reaches with the rig&#39;s right hand.</p><h2 id="poses" tabindex="-1">Poses <a class="header-anchor" href="#poses" aria-label="Permalink to &quot;Poses&quot;">​</a></h2>',2)),s(r,{name:"lib-poses",caption:"The Poses tab with a Docs group of four stick-figure cards (Guard, Wind up, Punch, Follow through) and the hint: Click to apply. Shift mirrored, Ctrl whole actor, Alt-drag to blend."}),t[6]||(t[6]=o('<p>Your pose library lives in your plugin settings, so each animator has their own. Poses that fit the selected rig are listed by group, each card drawn as a stick figure. Poses made on a rig that doesn&#39;t share at least half their joints sit dimmed under <strong>Other rigs</strong>.</p><table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Preview a pose</td><td>Hover its card (moving off puts the rig back)</td></tr><tr><td>Apply it</td><td>Click (<code>Shift</code> mirrored, <code>Ctrl</code> to the whole actor)</td></tr><tr><td>Blend toward it</td><td><code>Alt</code>-drag across the card, left edge 0%, right edge 100%</td></tr><tr><td>Save the current pose</td><td><strong>Save pose</strong>, then type its name</td></tr><tr><td>Assign a slot</td><td>Right click &gt; <strong>Assign to slot</strong> (1 to 9)</td></tr><tr><td>Apply a slot</td><td><code>Alt+1</code> to <code>Alt+9</code> over the viewport or the Timeline</td></tr><tr><td>Find a pose by name</td><td><code>Ctrl+Alt+P</code> opens the quick pose picker at the pointer</td></tr></tbody></table><p>Applying a pose works like posing by hand: it keys with Auto-key on, goes on the active layer, and is one undo step. It sets the picked joints, else every selected rig, else the scene&#39;s only rig. Deleting a pose or group shows an <strong>Undo</strong> button in the status line for 6 seconds, since plugin settings aren&#39;t in Studio&#39;s undo.</p><h2 id="sharing-presets" tabindex="-1">Sharing presets <a class="header-anchor" href="#sharing-presets" aria-label="Permalink to &quot;Sharing presets&quot;">​</a></h2><p><strong>Export presets...</strong> opens a window where you tick what to share: ease, generator, constraint and driver presets, poses, and the open scene&#39;s saved colours, gradients and sequences. <strong>Export</strong> puts them in a folder in ServerStorage and selects it. Right click it &gt; <strong>Save to File...</strong> to send it as a <code>.rbxm</code> or <code>.rbxmx</code>.</p><p>To bring presets in, insert the file into the place, select it in the Explorer and press <strong>Import presets</strong>. Taken names get a number. Nothing in a preset file is ever run.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Deleting a saved preset asks first: presets live in your plugin settings, outside Ctrl+Z.</li><li><strong>Save as preset...</strong> in any generator, constraint, driver or warp block menu opens the new preset in the Library with its name ready to type.</li></ul><h2 id="compared-to-roblox-s-animation-editor" tabindex="-1">Compared to Roblox&#39;s Animation Editor <a class="header-anchor" href="#compared-to-roblox-s-animation-editor" aria-label="Permalink to &quot;Compared to Roblox&#39;s Animation Editor&quot;">​</a></h2><p>Roblox&#39;s Animation Editor has no generators, constraints, drivers or Motion Warp, so it has no presets for them either. The Library&#39;s Generators, Constraints, Drivers and Warps tabs have no counterpart there.</p>',10))])}const k=n(h,[["render",p]]);export{f as __pageData,k as default};
